mapper.select:
SELECT L.LINK_SYS_CD,L.LINK_SYS_NM, , , MAX(D.ping_dt) AS CLCT_DT
FROM web_link_sys_info L
LEFT JOIN vw_tnms_gateway_device_live D ON D.link_sys_cd=L.LINK_SYS_CD AND D.stn_cd=#{stnCd}
     AND D.ems_id IN #{id}
WHERE L.USE_YN='Y' AND L.LINK_SYS_CD IN ('EMS_TX','VMS','PBX','EMS_PIDS','SCADA_SEC')
  AND L.LINK_SYS_CD IN #{code}
GROUP BY L.LINK_SYS_CD,L.LINK_SYS_NM
ORDER BY FIELD(L.LINK_SYS_CD,'VMS','PBX','SCADA_SEC','EMS_PIDS','EMS_TX')

SELECT DATE_FORMAT(R.reg_dt,'%Y-%m-%d %H:00') AS timeLabel,
       ROUND(AVG(R.cpu_usage),2) AS cpuVl,ROUND(AVG(R.memory_usage),2) AS mmryVl,ROUND(AVG(R.disk_usage),2) AS diskVl
FROM raw_usage_log R
JOIN com_device_info D ON D.ems_id=R.ems_id AND D.device_id=R.device_id AND D.use_yn='Y'
WHERE 1=1 
   AND D.ems_id=(CASE #{linkSysCd}
      WHEN 'EMS_TX' THEN 1 WHEN 'VMS' THEN 4 WHEN 'PBX' THEN 11 WHEN 'EMS_PIDS' THEN 13 WHEN 'SCADA_SEC' THEN 16 ELSE -1 END)
   AND D.stn_cd=#{stnCd}
   AND R.reg_dt >= #{startDt}
   AND R.reg_dt <= #{endDt}
   AND R.reg_dt >= DATE_SUB(NOW(),INTERVAL 24 HOUR)
   AND D.device_id=#{deviceId}
   AND SHA2(CONCAT(D.ems_id,':',D.device_id),256)=#{eqpmntSn}
   AND D.ems_id=#{emsId}
GROUP BY DATE_FORMAT(R.reg_dt,'%Y-%m-%d %H:00') ORDER BY MIN(R.reg_dt) LIMIT 240

SELECT FROM raw_event_action D WHERE D.event_yn=1 AND D.event_grade IN ('1','2','3','4','5')
AND D.ems_id IN #{id}
ORDER BY D.event_dt DESC,D.event_seq DESC LIMIT 500

SELECT 
FROM raw_event_action D 
WHERE D.event_seq=#{eventSeq}
  AND D.ems_id IN #{id}

SELECT ,
       D.event_edt AS dsbltyEndDt
FROM raw_event_log D 
WHERE D.event_seq=#{eventSeq}
  AND D.ems_id IN #{id}
